L["This replaces your own choices on Who to buff and When to offer. Continue?"] = "Das ersetzt Eure eigenen Einstellungen auf „Wen stärken“ und „Wann anbieten“. Fortfahren?"
L["This replaces the lines you wrote with the %s lines. Continue?"] = "Das ersetzt Eure selbst geschriebenen Sprüche durch die Sprüche von „%s“. Fortfahren?"
L["people who buff me"] = "wer mich stärkt"
L["my group"] = "meine Gruppe"
L["passers-by within %s"] = "Passanten bis %s"
L["passers-by"] = "Passanten"
L["myself"] = "mich selbst"
L["myself (outside cities and inns)"] = "mich selbst (außerhalb von Städten und Gasthäusern)"
L["nobody"] = "niemand"
L["topped up when low"] = "aufgefrischt, wenn er bald abläuft"
L["offered anyway"] = "trotzdem angeboten"
L["skipped"] = "übersprungen"
L["Offering to: %s."] = "Angebot an: %s."
L["Offering to: %s. Already buffed: %s."] = "Angebot an: %s. Bereits gestärkt: %s."
L["People who buff me are always offered one back."] = "Wer mich stärkt, bekommt den Gefallen immer erwidert."
L["People who ask in chat: on."] = "Anfragen im Chat: an."
L["Your class has no buffs for other players, and %s is off, so the prompt never appears."] = "Eure Klasse hat keine Stärkungszauber für andere Spieler, und %s ist ausgeschaltet, also erscheint die Anzeige nie."
L["Your class has no buffs for other players, and your own are all switched off on %s, so the prompt never appears."] = "Eure Klasse hat keine Stärkungszauber für andere Spieler, und Eure eigenen sind auf dem Reiter „%s“ alle ausgeschaltet, also erscheint die Anzeige nie."
L["Your class has no buffs for other players, so the prompt reminds you of your own: %s."] = "Eure Klasse hat keine Stärkungszauber für andere Spieler, also erinnert Euch die Anzeige an Eure eigenen: %s."
L["Not in cities and inns."] = "Nicht in Städten und Gasthäusern."
L["%s: none in your bags, so group buffs are not offered."] = "%s: keine in Euren Taschen, daher werden keine Gruppenzauber angeboten."
L["Group buffs when %d of a party need it (%s: %d in bags)."] = "Gruppenzauber, sobald %d Spieler einer Gruppe ihn brauchen (%s: %d in den Taschen)."
L["Group buffs when %d of a party need it."] = "Gruppenzauber, sobald %d Spieler einer Gruppe ihn brauchen."
L["Ready checks and the just-revived go first."] = "Vorrang beim Bereitschaftscheck und für gerade Wiederbelebte."
L["At a ready check, your group goes first."] = "Beim Bereitschaftscheck kommt Eure Gruppe zuerst."
L["The just-revived go first."] = "Gerade Wiederbelebte kommen zuerst."
L["Also /thanks people who buff you."] = "Bedankt sich außerdem per /thank bei allen, die Euch stärken."
L["The /thank waits for %s to be on."] = "Das /thank wartet, bis %s eingeschaltet ist."
L["People who buff me"] = "Wer mich stärkt"
L["Silent."] = "Schweigt."
L["Only /thank."] = "Nur /thank."
L["a whisper"] = "Flüstern"
L["Says %s in %s when you buff someone back."] = "Sagt %s per %s, wenn Ihr einen Gefallen erwidert."
L["Says %s in %s when you buff someone."] = "Sagt %s per %s, wenn Ihr jemanden stärkt."
L["Says one of your own lines in %s when you buff someone back."] = "Sagt einen Eurer eigenen Sprüche per %s, wenn Ihr einen Gefallen erwidert."
L["Says one of your own lines in %s when you buff someone."] = "Sagt einen Eurer eigenen Sprüche per %s, wenn Ihr jemanden stärkt."
L["Manners is on"] = "Manners ist eingeschaltet"
L["Manners is switched off, so the prompt will never appear. Everything below is still saved."] = "Manners ist ausgeschaltet, also erscheint die Anzeige nie. Alles unten bleibt gespeichert."
L["Your class has no buffs it can cast on another player."] = "Eure Klasse hat keine Stärkungszauber, die sie auf einen anderen Spieler wirken kann."
L["Manners has nothing to offer here. It is still worth keeping installed on an alt that does."] = "Manners hat hier nichts anzubieten. Für einen anderen Charakter, der etwas anbieten kann, lohnt es sich trotzdem, Manners installiert zu lassen."
L["Manners could not work out what you can cast."] = "Manners konnte nicht herausfinden, was Ihr wirken könnt."
L["Either your class has nothing for other players, or the spell probe came back empty -- %s says which."] = "Entweder hat Eure Klasse nichts für andere Spieler, oder die Zauberabfrage kam leer zurück – %s verrät, was davon zutrifft."
L["Manners shows a small button, the prompt, with the next person to buff. Click it, or press your key, and it casts on them; the game does not let addons cast by themselves."] = "Manners zeigt eine kleine Schaltfläche, die Anzeige, mit der nächsten Person zum Stärken. Klickt darauf oder drückt Eure Taste, dann wird der Zauber auf diese Person gewirkt; von selbst dürfen Addons nicht zaubern."
L["The prompt is unlocked, so it will not cast."] = "Die Anzeige ist entsperrt und wirkt daher nichts."
L["Lock it"] = "Sperren"
L["These settings are shared by your other characters (profile: %s)."] = "Diese Einstellungen teilt Ihr mit Euren anderen Charakteren (Profil: %s)."
L["The Profiles tab also copies settings as text to share."] = "Auf dem Reiter „Profile“ lassen sich Einstellungen auch als Text zum Teilen kopieren."
L["Give this character its own settings"] = "Eigene Einstellungen für diesen Charakter"
L["Copies these settings into a profile named after this character; changes made after that stay on this character."] = "Kopiert diese Einstellungen in ein Profil mit dem Namen dieses Charakters; spätere Änderungen gelten nur für diesen Charakter."
L["1. Who to buff"] = "1. Wen stärken"
L["Offer my buff to"] = "Wer meinen Stärkungszauber bekommt"
L["A starting point; fine-tune it on Who to buff."] = "Ein Ausgangspunkt; die Feinheiten stellt Ihr auf dem Reiter „Wen stärken“ ein."
L["2. Put it on a key"] = "2. Auf eine Taste legen"
L["Key that buffs the prompted player"] = "Taste zum Stärken des angezeigten Spielers"
L["Saved with your game key bindings, so it works on every profile."] = "Wird mit den Tastenbelegungen des Spiels gespeichert und gilt daher für jedes Profil."
L["Open key bindings"] = "Tastenbelegung öffnen"
L["Opens Options > Keybindings > Manners, the game's own key bindings."] = "Öffnet Optionen > Tastaturbelegung > Manners, die Tastenbelegung des Spiels."
L["Make a macro"] = "Makro erstellen"
L["Adds a macro named Manners; put it on an action bar and pressing it clicks the prompt."] = "Legt ein Makro namens Manners an; zieht es auf eine Aktionsleiste, dann löst ein Klick darauf die Anzeige aus."
L["Ready: %s buffs whoever the prompt shows."] = "Bereit: %s stärkt, wen die Anzeige zeigt."
L["Your Manners macro is made: open the macro window (/macro) and drag it onto an action bar."] = "Euer Manners-Makro ist erstellt: Öffnet das Makrofenster (/macro) und zieht es auf eine Aktionsleiste."
L["No key yet: pick one above, make the macro, or just click the prompt."] = "Noch keine Taste: Wählt oben eine, erstellt das Makro oder klickt einfach auf die Anzeige."
L["3. See it"] = "3. Ansehen"
L["Stop preview"] = "Vorschau beenden"
L["Show me the prompt"] = "Anzeige ansehen"
L["Shows a sample prompt so you can see it and put it where you want."] = "Zeigt eine Beispielanzeige, damit Ihr sie seht und dorthin schieben könnt, wo Ihr sie haben wollt."
L["Where it sits"] = "Position"
L["Pick Above the action bars to put it back where it started."] = "Wählt „Über den Aktionsleisten“, um die Anzeige an ihren ursprünglichen Platz zurückzusetzen."
L["Above the action bars (default)"] = "Über den Aktionsleisten (Standard)"
L["Where I dragged it"] = "Wohin ich sie gezogen habe"
L["Lock position"] = "Position sperren"
L["Unlock to drag the prompt; it will not cast until you lock it again."] = "Entsperrt die Anzeige, um sie zu verschieben; bis Ihr sie wieder sperrt, wirkt sie nichts."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "entsperrt, aber das Addon ist |cffff8080aus|r, also gibt es keine Anzeige zum Verschieben – schaltet es zuerst ein."
L["4. Say thanks (optional)"] = "4. Danke sagen (optional)"
L["When I buff someone"] = "Wenn ich jemanden stärke"
L["Change the words and channel on What I say."] = "Wortlaut und Kanal ändert Ihr auf dem Reiter „Was ich sage“."
L["Only when I buff someone back"] = "Nur wenn ich einen Gefallen erwidere"
L["Off, you also speak when you buff someone first."] = "Ist dies aus, sprecht Ihr auch, wenn Ihr jemanden zuerst stärkt."
L["Snooze"] = "Pausieren"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100Pausiert bis %s.|r Im Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und folgt der Pause, sobald der Kampf vorbei ist."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100Pausiert bis %s.|r Die Anzeige ist entsperrt, bleibt also zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100Pausiert bis %s.|r Bis dahin keine Anzeige, aber wer Euch stärkt, wird trotzdem bemerkt."
L["Hide the prompt for a while without turning Manners off."] = "Blendet die Anzeige eine Weile aus, ohne Manners auszuschalten."
L["Snooze %s"] = "%s pausieren"
L["Stop snoozing"] = "Pause beenden"
L["Open the ledger"] = "Gefallen-Buch öffnen"
L["Who buffed you, whether you returned it, and who you buffed first."] = "Wer Euch gestärkt hat, ob Ihr den Gefallen erwidert habt und wen Ihr zuerst gestärkt habt."
L["Minimap and chat"] = "Minikarte und Chat"
L["Show minimap button"] = "Minikartensymbol anzeigen"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners bleibt so oder so im Addon-Menü an der Minikarte."
L["Without it, open these settings with %s or Options > AddOns."] = "Ohne es öffnet Ihr diese Einstellungen mit %s oder über Optionen > AddOns."
L["Tell me in chat what Manners is doing"] = "Im Chat melden, was Manners tut"
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Eine Zeile, wenn Euch jemand stärkt, wenn ein Gefallen als erwidert gilt und wenn ein Klick fehlschlägt, übersprungen wird oder ein Gefallen danach noch offen ist."
L["Only you see these; they show whether a buff was missed or someone could not be reached."] = "Nur Ihr seht diese Zeilen; sie zeigen, ob ein Stärkungszauber verpasst wurde oder jemand nicht erreichbar war."
L["%s: the game does not say how many you carry."] = "%s: Das Spiel verrät nicht, wie viele Ihr dabeihabt."
L["%s: %d in your bags"] = "%s: %d in Euren Taschen"
L["You have not learned a group version of your buffs yet."] = "Ihr habt noch keine Gruppenversion Eurer Stärkungszauber erlernt."
L["What to cast"] = "Welcher Zauber"
L["Buff to offer"] = "Angebotener Zauber"
L["You offer %s."] = "Ihr bietet %s an."
L["%s is not offered to players without mana, such as warriors and rogues."] = "%s wird Spielern ohne Mana, etwa Kriegern und Schurken, nicht angeboten."
L["%s are not offered to players without mana, such as warriors and rogues."] = "%s werden Spielern ohne Mana, etwa Kriegern und Schurken, nicht angeboten."
L["Nothing is ticked here, so the prompt will never appear."] = "Hier ist nichts angehakt, also erscheint die Anzeige nie."
L["Offer a buff back to anyone who buffs you. Yours reaches only your own party (in a raid, your subgroup), so someone outside it is offered once they join."] = "Erwidert jedem den Gefallen, der Euch stärkt. Euer Zauber erreicht nur Eure eigene Gruppe (im Schlachtzug Eure Untergruppe), also bekommt jemand von außerhalb erst etwas angeboten, sobald er beitritt."
L["Offer a buff back to anyone who buffs you. Yours reaches only your group, so someone outside it is offered once they join."] = "Erwidert jedem den Gefallen, der Euch stärkt. Euer Zauber erreicht nur Eure Gruppe, also bekommt jemand von außerhalb erst etwas angeboten, sobald er beitritt."
L["Offer a buff back to anyone who buffs you, in your group or not."] = "Erwidert jedem den Gefallen, der Euch stärkt, ob in Eurer Gruppe oder nicht."
L["My party and raid"] = "Meine Gruppe und mein Schlachtzug"
L["Passers-by (players near me, not in my group)"] = "Passanten (Spieler in meiner Nähe, nicht in meiner Gruppe)"
L["Seen through nameplates, your target, focus and mouseover."] = "Erkannt über Namensplaketten, Euer Ziel, Euren Fokus und Mouseover."
L["Everything you can offer is cast on yourself and reaches only your party, so there is nothing for passers-by."] = "Alles, was Ihr anbieten könnt, wirkt Ihr auf Euch selbst, und es erreicht nur Eure Gruppe, also gibt es für Passanten nichts."
L["Passers-by within"] = "Entfernung für Passanten"
L["Only passers-by are measured, and only roughly: the game gives no exact distance."] = "Gemessen wird nur bei Passanten, und nur grob: Das Spiel nennt keine genaue Entfernung."
L["Only in cities and inns"] = "Nur in Städten und Gasthäusern"
L["Out in the world, passers-by are left alone; your group and people who buff you are offered anywhere."] = "Draußen in der Welt werden Passanten in Ruhe gelassen; Eure Gruppe und wer Euch stärkt, bekommen überall etwas angeboten."
L["For a minute, offer your buff to someone who asks for it (\"fort pls\"); off by default because chat is guesswork."] = "Bietet eine Minute lang jemandem Euren Stärkungszauber an, der darum bittet („fort pls“); standardmäßig aus, weil das Lesen des Chats Rätselraten ist."
L["Myself"] = "Ich selbst"
L["Offer your own buffs to you when one is not up: the ones below. They are cast on you, your target is handed back, and nothing is said."] = "Bietet Euch Eure eigenen Stärkungszauber an, wenn einer nicht aktiv ist: die unten aufgeführten. Sie werden auf Euch gewirkt, Euer Ziel wird wiederhergestellt, und es wird nichts gesagt."
L["Offer your own buffs to you too, when one is not up: the ones below, and the buff you give others. They are cast on you, your target is handed back, and nothing is said."] = "Bietet Euch auch Eure eigenen Stärkungszauber an, wenn einer nicht aktiv ist: die unten aufgeführten und den Stärkungszauber, den Ihr anderen gebt. Sie werden auf Euch gewirkt, Euer Ziel wird wiederhergestellt, und es wird nichts gesagt."
L["Offer your own buff to you too, when you are missing it or, with top-ups on, it is running low. It is cast on you, your target is handed back, and nothing is said."] = "Bietet auch Euch selbst Euren Stärkungszauber an, wenn er Euch fehlt oder, bei eingeschalteter Auffrischung, bald abläuft. Er wird auf Euch gewirkt, Euer Ziel wird wiederhergestellt, und es wird nichts gesagt."
L["Off: nothing is offered to you while the game calls you resting, in a city or an inn."] = "Aus: Ihr bekommt nichts angeboten, solange Ihr laut Spiel in einer Stadt oder einem Gasthaus seid."
L["My group and raid"] = "Meine Gruppe und mein Schlachtzug"
L["Use group buffs"] = "Gruppenzauber verwenden"
L["When this many need it"] = "Ab so vielen Spielern"
L["Raid groups I buff"] = "Untergruppen, die ich stärke"
L["In a raid, only these groups are offered your buff; people who buff you or ask are offered anyway."] = "Im Schlachtzug bekommen nur diese Gruppen Euren Stärkungszauber angeboten; wer Euch stärkt oder darum bittet, bekommt ihn trotzdem angeboten."
L["Who comes first"] = "Reihenfolge"
L["My target first"] = "Mein Ziel zuerst"
L["Your target goes ahead of everyone when the game can see they lack the buff."] = "Euer Ziel kommt vor allen anderen, wenn das Spiel erkennt, dass ihm der Stärkungszauber fehlt."
L["Greyed out while |cffffd100Always offer|r is chosen on %s: nothing is read then."] = "Ausgegraut, solange |cffffd100Immer anbieten|r auf dem Reiter „%s“ gewählt ist: Dann wird nichts ausgelesen."
L["Friends and guildmates first"] = "Freunde und Gildenmitglieder zuerst"
L["Only changes the order; nobody is added or left out."] = "Ändert nur die Reihenfolge; niemand kommt hinzu oder fällt weg."
L["My group first at a ready check"] = "Meine Gruppe zuerst beim Bereitschaftscheck"
L["From a ready check until the pull, group members missing your buff go first."] = "Vom Bereitschaftscheck bis zum Kampfbeginn kommen Gruppenmitglieder zuerst, denen Euer Stärkungszauber fehlt."
L["Group members just revived first"] = "Gerade wiederbelebte Gruppenmitglieder zuerst"
L["For two minutes after someone is brought back, they go first if they lack your buff."] = "Zwei Minuten nach einer Wiederbelebung kommt die Person zuerst, wenn ihr Euer Stärkungszauber fehlt."
L["Who to skip"] = "Wen überspringen"
L["Skip players below level"] = "Mindeststufe"
L["Someone known only by name is offered anyway."] = "Wer nur mit Namen bekannt ist, bekommt trotzdem etwas angeboten."
L["Skip players out of range"] = "Spieler außer Reichweite überspringen"
L["If the game cannot tell the range they are still offered."] = "Kann das Spiel die Reichweite nicht bestimmen, bekommen sie trotzdem etwas angeboten."
L["Skip players flagged for PvP"] = "Für PvP markierte Spieler überspringen"
L["Buffing somebody flagged for PvP flags you too. Ignored while you are flagged yourself, as in a battleground, but not while your own flag is running out."] = "Stärkt Ihr jemanden, der für PvP markiert ist, werdet Ihr ebenfalls markiert. Das entfällt, solange Ihr selbst markiert seid, etwa auf einem Schlachtfeld, aber nicht, während Eure eigene Markierung abläuft."
L["Never offer"] = "Nie etwas anbieten"
L["Nobody is on the list. Shift-right-click the prompt to add the person it shows, or type a name below."] = "Niemand steht auf der Liste. Umschalt-Rechtsklick auf die Anzeige setzt die gezeigte Person darauf, oder gebt unten einen Namen ein."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Eine Person steht auf der Liste. Sie bekommt nie etwas angeboten, weder als Passant noch als Mitglied Eurer Gruppe."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "%d Personen stehen auf der Liste. Sie bekommen nie etwas angeboten, weder als Passanten noch als Mitglieder Eurer Gruppe."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Stärkt Euch jemand von der Liste, wird Euch trotzdem angeboten, den Gefallen zu erwidern. Mit Umschalt-Rechtsklick auf diese Person in der Anzeige lasst Ihr diesen Gefallen verfallen."
L["Add a name"] = "Namen hinzufügen"
L["Type it as the prompt shows it and press Enter."] = "Gebt ihn so ein, wie die Anzeige ihn zeigt, und drückt die Eingabetaste."
L["Pick a name"] = "Namen wählen"
L["Remove from list"] = "Von der Liste entfernen"
L["Clear the list"] = "Liste leeren"
L["Take everybody off the never-offer list?"] = "Alle von der Ausschlussliste nehmen?"
L["Already buffed"] = "Bereits gestärkt"
L["If they already have it"] = "Wenn sie ihn schon haben"
L["Your own buffs are offered when none is up; with Offer a top-up when it runs low, also when one is running out (never an aura or an aspect)."] = "Eure eigenen Stärkungszauber werden angeboten, wenn keiner aktiv ist; mit „Auffrischen, wenn er bald abläuft“ auch, wenn einer bald abläuft (nie eine Aura oder ein Aspekt)."
L["Someone who buffed you is always offered a buff back; Diagnostics shows which buffs Manners can see on others."] = "Wer Euch gestärkt hat, bekommt den Gefallen immer erwidert; „Diagnose“ zeigt, welche Stärkungszauber Manners bei anderen sieht."
L["Skip them (default)"] = "Überspringen (Standard)"
L["Offer a top-up when it runs low"] = "Auffrischen, wenn er bald abläuft"
L["Always offer (costs a lot of mana)"] = "Immer anbieten (kostet viel Mana)"
L["Top up when less than this is left (minutes)"] = "Auffrischen bei weniger als (Minuten)"
L["Someone whose time left cannot be read is not offered a top-up, unless they buffed you."] = "Wessen Restdauer sich nicht auslesen lässt, bekommt keine Auffrischung angeboten, außer die Person hat Euch gestärkt."
L["Everyone you offer to is offered again and again, even with a fresh buff."] = "Alle, denen Ihr etwas anbietet, bekommen es immer wieder angeboten, auch mit frischem Stärkungszauber."
L["%s does nothing in this mode."] = "%s bewirkt in diesem Modus nichts."
L["Hold back"] = "Zurückhalten"
L["Casting would dismount you; it is always hidden while dead, on a flight path or in a vehicle."] = "Beim Wirken müsstet Ihr absteigen; tot, auf einer Flugroute oder in einem Fahrzeug ist die Anzeige immer ausgeblendet."
L["Below this, only your own buff and people who buffed you or asked are offered."] = "Darunter bekommen nur Ihr selbst und alle, die Euch gestärkt oder darum gebeten haben, etwas angeboten."
L["Below this, only people who buffed you or asked are offered."] = "Darunter bekommt nur etwas angeboten, wer Euch gestärkt oder darum gebeten hat."
L["Off: buffs are offered at any mana."] = "Aus: Stärkungszauber werden bei jedem Manastand angeboten."
L["Below %d%% only favours, requests and your own buff are offered; the rest come back at %d%%."] = "Unter %d%% werden nur Gefallen, Anfragen und Euer eigener Stärkungszauber angeboten; der Rest kommt ab %d%% wieder."
L["Below %d%% only favours and requests are offered; the rest come back at %d%%."] = "Unter %d%% werden nur Gefallen und Anfragen angeboten; der Rest kommt ab %d%% wieder."
L["How long someone who buffed you stays on offer: %s."] = "Wie lange jemand, der Euch gestärkt hat, in der Anzeige bleibt: %s."
L["Offer a buff back for (seconds)"] = "Zeit zum Erwidern (Sekunden)"
L["Fantasy (general)"] = "Fantasy (allgemein)"
L["loaded the %s lines."] = "die Zeilen von „%s“ geladen."
L["In combat: changes here apply once the fight ends."] = "Im Kampf: Änderungen hier gelten erst nach dem Kampf."
L["Optional: thank people, or say a line, when you buff them. %s also has quick choices for this."] = "Optional: Bedankt Euch oder sagt einen Spruch, wenn Ihr jemanden stärkt. Auch auf dem Reiter „%s“ gibt es dafür eine schnelle Auswahl."
L["Thanks and speech"] = "Dank und Sprüche"
L["/thank people who buff me"] = "Mit /thank danken, wenn mich jemand stärkt"
L["Everyone near you sees it; never in combat or instances, and at most once per person every five minutes."] = "Alle in Eurer Nähe sehen es; nie im Kampf oder in Instanzen und höchstens alle fünf Minuten einmal pro Person."
L["Say a line when I buff someone"] = "Beim Stärken einen Spruch sagen"
L["Where to say it"] = "Kanal"
L["Whisper them sends it only to the person you buff."] = "„Anflüstern“ schickt ihn nur an die Person, die Ihr stärkt."
L["Say"] = "Sagen"
L["Whisper them"] = "Anflüstern"
L["Emote"] = "Emote"
L["Party"] = "Gruppe"
L["Raid"] = "Schlachtzug"
L["Yell"] = "Schreien"
L["Tick Say a line to choose what you say."] = "Hakt „Beim Stärken einen Spruch sagen“ an, um zu wählen, was Ihr sagt."
L["Lines"] = "Sprüche"
L["Line set"] = "Vorlage"
L["Replaces the lines below."] = "Ersetzt die Sprüche unten."
L["Replace everything in the box below with the %s lines?"] = "Alles im Feld unten durch die Zeilen von „%s“ ersetzen?"
L["One line is picked at random. Placeholders: {name} their name, {buff} the spell."] = "Ein Spruch wird zufällig gewählt. Platzhalter: {name} der Name, {buff} der Zauber."
L["A line too long for a macro is skipped; Try a few shows what would go out."] = "Ein Spruch, der für ein Makro zu lang ist, wird übersprungen; „Ein paar Sprüche testen“ zeigt, was gesendet würde."
L["In character picks a line when you click, to fit your race, faction, class and the moment. Editing the lines below turns it off."] = "„Passend zum Charakter“ wählt beim Klick einen Spruch, der zu Volk, Fraktion, Klasse und Moment passt. Bearbeitet Ihr die Sprüche unten, wird es ausgeschaltet."
L["Your lines (one per line)"] = "Eure Sprüche (einer pro Zeile)"
L["Editing these turns In character off and uses only your lines. Continue?"] = "Bearbeiten schaltet „Passend zum Charakter“ aus, und nur Eure Sprüche werden verwendet. Fortfahren?"
L["Go back to In character"] = "Zurück zu „Passend zum Charakter“"
L["Try a few lines"] = "Ein paar Sprüche testen"
L["Prints sample lines in your chat; only you see them."] = "Zeigt Beispielsprüche in Eurem Chat; nur Ihr seht sie."
L["Somebody"] = "Jemand"
L["A line goes out when you click, even if the cast then fails out of range or line of sight."] = "Eine Zeile geht beim Klick raus, auch wenn der Zauber danach an Reichweite oder Sichtlinie scheitert."
L["In combat: changes here show once the fight ends."] = "Im Kampf: Änderungen hier werden erst nach dem Kampf sichtbar."
L["Preview"] = "Vorschau"
L["Shows a sample prompt to style; it stays while this window is open."] = "Zeigt eine Beispielanzeige zum Gestalten; sie bleibt, solange dieses Fenster offen ist."
L["Dragging the prompt afterwards sets this to Where I dragged it."] = "Verschiebt Ihr die Anzeige danach, steht hier „Wohin ich sie gezogen habe“."
