L["Panel colour"] = "Hintergrundfarbe"
L["Colour marker by reason"] = "Farbmarkierung nach Grund"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Blassgelb für Euer eigenes Ziel, Orange für einen offenen Gefallen, Tiefrosa für jemanden, der darum gebeten hat, Himmelblau für Eure Gruppe, Violett für Passanten – in dieser Reihenfolge bekommen sie etwas angeboten."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Hellblau für Euer eigenes Ziel, Bernsteingelb für einen offenen Gefallen, Rosa für jemanden, der darum gebeten hat, dunkleres Blau für Eure Gruppe, Grau für Passanten – in dieser Reihenfolge bekommen sie etwas angeboten."
L["A colour that shows why this person is on the prompt."] = "Eine Farbe, die zeigt, warum diese Person in der Anzeige steht."
L["Reason colours"] = "Farben der Gründe"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "Der Satz „Für Farbenblinde“ hält die Gründe bei Rot-Grün-Sehschwäche auseinander, mit Farben, die sich auch in der Helligkeit unterscheiden."
L["Standard"] = "Standard"
L["Colour-blind friendly"] = "Für Farbenblinde"
L["Marker colour"] = "Markierungsfarbe"
L["Used when Colour marker by reason is off."] = "Gilt, wenn „Farbmarkierung nach Grund“ aus ist."
L["Colour marker"] = "Farbmarkierung"
L["Framed panels have no stripe."] = "Das Aussehen „Gerahmt“ hat keinen Streifen."
L["Ring around the icon"] = "Ring um das Symbol"
L["Stripe on the left edge"] = "Streifen am linken Rand"
L["Both"] = "Beides"
L["None"] = "Keine"
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Der Ring wird hinter dem Symbol gezeichnet, das ausgeschaltet ist, und das Aussehen „Gerahmt“ hat keinen Streifen."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Das Abrunden des Symbols ersetzt den Ring durch eine Maske, und das Aussehen „Gerahmt“ hat keinen Streifen."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "Es gibt nichts mehr zu färben: Der Ring wird hinter dem Symbol gezeichnet, das ausgeschaltet ist."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "Es gibt nichts mehr zu färben: Das Abrunden des Symbols ersetzt den Ring durch eine Maske."
L["There is nothing left to colour: the framed look has no stripe."] = "Es gibt nichts mehr zu färben: Das Aussehen „Gerahmt“ hat keinen Streifen."
L["Getting my attention"] = "Aufmerksamkeit"
L["Flash when someone buffs me"] = "Aufblitzen, wenn mich jemand stärkt"
L["Needs the icon, the stripe or Full animations."] = "Braucht das Symbol, den Streifen oder Animationen auf „Voll“."
L["Pulse until I buff them back"] = "Pulsieren, bis ich den Gefallen erwidere"
L["Flash once"] = "Einmal aufblitzen"
L["Animations"] = "Animationen"
L["Calm drops the light sweep, the shake and the fade-out."] = "„Ruhig“ lässt den Lichtschimmer, das Wackeln und das Ausblenden weg."
L["Full"] = "Voll"
L["Calm (less movement)"] = "Ruhig (weniger Bewegung)"
L["Keep the prompt dim and still in combat"] = "Anzeige im Kampf abgedunkelt und still halten"
L["It stays on screen in combat because your key binding would still cast; this only stops the flashes that say what a click did, red if it failed."] = "Sie bleibt im Kampf sichtbar, weil Eure Tastenbelegung trotzdem wirken würde; dies stoppt nur das Aufblitzen, das zeigt, was ein Klick bewirkt hat, rot bei einem Fehlschlag."
L["Play a sound"] = "Sound abspielen"
L["When a new person appears on the prompt."] = "Wenn eine neue Person in der Anzeige erscheint."
L["Sound"] = "Sound"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(nicht geladen)|r"
L["Only for people who buff me"] = "Nur bei Spielern, die mich stärken"
L["Off, every new person makes a sound, passers-by included."] = "Ist dies aus, macht jede neue Person einen Sound, auch Passanten."
L["%s is silent. Pick a sound above."] = "%s ist stumm. Wählt oben einen Sound."
L["Text"] = "Text"
L["Font"] = "Schriftart"
L["Font size"] = "Schriftgröße"
L["Text colour"] = "Textfarbe"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while this is on:"] = "Bleibt sie auf Weiß, wird der Text auf hellem Hintergrund von selbst dunkel. Andere Farben werden wie gewählt verwendet, außer bei Namen, solange dies eingeschaltet ist:"
L["Colour names by class"] = "Namen in Klassenfarbe"
L["Show a second line"] = "Zweite Zeile anzeigen"
L["Needs a prompt at least %d pixels tall."] = "Braucht eine Anzeige von mindestens %d Pixeln Höhe."
L["Change what the prompt says: %s."] = "Was die Anzeige sagt, ändert Ihr unter %s."
L["Prompt wording"] = "Wortlaut der Anzeige"
L["Icon and waiting list"] = "Symbol und Warteliste"
L["Show spell icon"] = "Zaubersymbol anzeigen"
L["Icon size"] = "Symbolgröße"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Bleibt innerhalb der Anzeige – macht sie zuerst höher oder breiter, um ein größeres Symbol zu bekommen."
L["The icon is held at %d to fit a prompt %d wide."] = "Das Symbol bleibt bei %d, damit es in eine %d breite Anzeige passt."
L["The icon is held at %d to fit a prompt %d high."] = "Das Symbol bleibt bei %d, damit es in eine %d hohe Anzeige passt."
L["Round the icon off"] = "Symbol abrunden"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Maskiert das Symbol zu einem Kreis. Das wirkt eher wie ein Porträt als wie ein Zauber, daher ist es standardmäßig aus."
L["Show the global cooldown on the icon"] = "Globale Abklingzeit auf dem Symbol anzeigen"
L["Sweeps the spell icon while the global cooldown runs, like your action bars, so you can see when the next press will go through."] = "Zeigt auf dem Zaubersymbol die globale Abklingzeit an, wie Eure Aktionsleisten, damit Ihr seht, wann der nächste Klick durchgeht."
L["Not in a fight while this is on:"] = "Nicht im Kampf, solange dies eingeschaltet ist:"
L["Show how many are waiting"] = "Anzahl der Wartenden anzeigen"
L["List the next few below"] = "Die nächsten darunter auflisten"
L["How many to list"] = "Wie viele auflisten"
L["The defaults suit most players; change these only if something bothers you."] = "Die Standardwerte passen für die meisten Spieler; ändert sie nur, wenn Euch etwas stört."
L["In combat: targeting changes apply once the fight ends."] = "Im Kampf: Änderungen an der Zielauswahl gelten erst nach dem Kampf."
L["Put these back to default"] = "Auf Standard zurücksetzen"
L["Put every setting on this tab back to its default? This also restores what the prompt says; where it sits is kept."] = "Alle Einstellungen auf diesem Reiter auf Standard zurücksetzen? Das stellt auch den Wortlaut der Anzeige wieder her; ihre Position bleibt erhalten."
L["Ignore shields, heals and trinket procs"] = "Schilde, Heilungen und Schmuckstückeffekte ignorieren"
L["Only class buffs such as Fortitude count as a favour to return."] = "Nur Klassen-Stärkungszauber wie Seelenstärke zählen als Gefallen, den es zu erwidern gilt."
L["How long someone who buffed you stays on offer."] = "Wie lange jemand, der Euch gestärkt hat, in der Anzeige bleibt."
L["Stop sooner if they are probably gone"] = "Wahrscheinlich Weitergezogene früher entfernen"
L["Someone who buffed you rarely can be range-checked, so they are let go after the time below."] = "Bei jemandem, der Euch gestärkt hat, lässt sich die Reichweite selten prüfen, daher wird die Person nach der Zeit unten entfernt."
L["Let them go after (seconds)"] = "Entfernen nach (Sekunden)"
L["Counted from their buff, not from when they walked off."] = "Gezählt ab dem Stärkungszauber, nicht ab dem Weggehen."
L["Turning it off forgets what is already kept."] = "Beim Ausschalten wird vergessen, was bereits gemerkt ist."
L["Timing"] = "Zeitsteuerung"
L["Don't repeat a spell on someone for (seconds)"] = "Keine Wiederholung auf dieselbe Person für (Sekunden)"
L["In case the cast failed; right-clicking the prompt skips the person for this long."] = "Falls der Zauber fehlschlug; ein Rechtsklick auf die Anzeige überspringt die Person so lange."
L["Check for people every (seconds)"] = "Suchlauf alle (Sekunden)"
L["Lower reacts faster and uses a little more CPU."] = "Niedriger reagiert schneller und braucht etwas mehr CPU."
L["Targeting"] = "Zielauswahl"
L["Hand my target back afterwards"] = "Danach mein Ziel wiederherstellen"
L["The prompt has to target someone to buff them; this puts your old target back."] = "Die Anzeige muss jemanden ins Ziel nehmen, um die Person zu stärken; dies stellt danach Euer vorheriges Ziel wieder her."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Alles, was Ihr anbieten könnt, wirkt Ihr auf Euch selbst, und von dort erreicht es Eure Gruppe, also ändert die Anzeige nie Euer Ziel und muss auch keines wiederherstellen."
L["Left / right"] = "Links / rechts"
L["Up / down"] = "Oben / unten"
L["Placeholders: {name} their name, {reason} why, {count} how many others are waiting, {class} their class, {buff} the spell, {time} time left on their buff (top-ups only)."] = "Platzhalter: {name} der Name, {reason} der Grund, {count} wie viele sonst noch warten, {class} die Klasse, {buff} der Zauber, {time} Restdauer des Stärkungszaubers (nur bei Auffrischung)."
L["The second line always shows the reason."] = "Die zweite Zeile zeigt immer den Grund."
L["First line"] = "Erste Zeile"
L["Reason text: my target"] = "Grund: mein Ziel"
L["Shown when your target is first in line."] = "Wird gezeigt, wenn Euer Ziel an erster Stelle steht."
L["Reason text: buffed me"] = "Grund: hat mich gestärkt"
L["Reason text: asked in chat"] = "Grund: im Chat gefragt"
L["Shown for someone who asked in chat."] = "Wird für jemanden gezeigt, der im Chat gefragt hat."
L["Reason text: my own buff"] = "Grund: eigener Stärkungszauber"
L["Shown when the prompt offers you your own buff."] = "Wird gezeigt, wenn die Anzeige Euch Euren eigenen Stärkungszauber anbietet."
L["Reason text: my group"] = "Grund: meine Gruppe"
L["Reason text: passer-by"] = "Grund: Passant"
L["Reason text: top-up"] = "Grund: Auffrischung"
L["{time} is how long theirs has left."] = "{time} zeigt, wie lange der Stärkungszauber noch hält."
L["Reason text: can't tell"] = "Grund: nicht erkennbar"
L["Shown when the game hides whether they already have it."] = "Wird gezeigt, wenn das Spiel verbirgt, ob die Person ihn schon hat."
L["Messages in chat"] = "Meldungen im Chat"
L["Log every click (noisy)"] = "Jeden Klick protokollieren (viele Meldungen)"
L["Prints what the prompt held and what the game did, to work out why a cast failed."] = "Zeigt, was in der Anzeige stand und was das Spiel getan hat, um herauszufinden, warum ein Zauber fehlschlug."
L["What Manners can see"] = "Was Manners sieht"
L["Class: |cffffffff%s|r"] = "Klasse: |cffffffff%s|r"
L["learned: |cff00ff00yes|r"] = "erlernt: |cff00ff00ja|r"
L["learned: |cff808080no|r"] = "erlernt: |cff808080nein|r"
L["can see who has it: |cff00ff00yes|r"] = "sieht, wer ihn hat: |cff00ff00ja|r"
L["can see who has it: |cffff8080no|r"] = "sieht, wer ihn hat: |cffff8080nein|r"
L["this client has never heard of spell %s, so Manners will never offer this one. That is a mistake in Manners -- please report it."] = "dieser Client kennt Zauber %s überhaupt nicht, daher wird Manners ihn nie anbieten. Das ist ein Fehler in Manners – bitte meldet ihn."
L["this client doesn't know spell %s, so somebody already carrying that version may be offered this anyway. That is a mistake in Manners -- please report it."] = "dieser Client kennt Zauber %s nicht, daher bekommt jemand, der diese Version schon trägt, diesen Stärkungszauber womöglich trotzdem angeboten. Das ist ein Fehler in Manners – bitte meldet ihn."
L["Where Manners cannot see a buff, people are still offered, but some may already have it."] = "Wo Manners einen Stärkungszauber nicht sieht, bekommen die Spieler trotzdem etwas angeboten, aber manche haben ihn vielleicht schon."
L["Flagged for PvP"] = "Für PvP markiert"
L["Passer-by distance: %s"] = "Entfernung für Passanten: %s"
L["Nothing to report: this character has no buffs it can put on another player."] = "Nichts zu melden: Dieser Charakter hat keine Stärkungszauber, die er auf andere Spieler wirken kann."
L["Errors this session"] = "Fehler in dieser Sitzung"
L["(%d in all this session, %d kept -- |cffffd100%s|r)"] = "(%d insgesamt in dieser Sitzung, %d aufbewahrt – |cffffd100%s|r)"
L["(%d in all this session -- |cffffd100%s|r)"] = "(%d insgesamt in dieser Sitzung – |cffffd100%s|r)"
L["Nothing has gone wrong this session."] = "In dieser Sitzung ist nichts schiefgegangen."
L["Reporting a bug"] = "Fehler melden"
L["Hide the report"] = "Bericht ausblenden"
L["Copy for a bug report"] = "Für Fehlerbericht kopieren"
L["Opens a box with the build, what this client allows, the settings that matter and anything that has broken, ready to copy."] = "Öffnet ein Feld mit der Version, den Angaben unter „Was dieser Client erlaubt“, den wichtigen Einstellungen und allen aufgetretenen Fehlern, bereit zum Kopieren."
L["Every character uses the Default profile unless you pick another here; make one per character for different settings."] = "Jeder Charakter nutzt das Standardprofil, sofern Ihr hier kein anderes wählt; legt pro Charakter eines an, um unterschiedliche Einstellungen zu haben."
L["To share settings as text, see Share as text at the bottom."] = "Um Einstellungen als Text zu teilen, seht unten unter „Als Text teilen“ nach."
L["Share as text"] = "Als Text teilen"
L["Copy your settings as text to share, or paste text someone gave you. Pasting keeps your own on/off, lock, position, minimap button and chat options, and never turns on Say a line."] = "Kopiert Eure Einstellungen als Text zum Teilen, oder fügt Text ein, den Euch jemand gegeben hat. Beim Einfügen bleiben Euer An/Aus, die Sperre, die Position, das Minikartensymbol und die Chat-Optionen erhalten, und „Beim Stärken einen Spruch sagen“ wird nie eingeschaltet."
L["Hide the text"] = "Text ausblenden"
L["Show my settings as text"] = "Meine Einstellungen als Text zeigen"
L["Shows your settings as text below, ready to copy; %s does the same."] = "Zeigt Eure Einstellungen unten als Text zum Kopieren; %s macht dasselbe."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Klickt in das Feld, drückt Strg+A, um alles zu markieren, dann Strg+C zum Kopieren (am Mac Cmd)."
L["Paste settings here, then press Accept"] = "Einstellungen hier einfügen, dann „Annehmen“ drücken"
L["Replaces this profile's settings; %s puts yours back."] = "Ersetzt die Einstellungen dieses Profils; %s stellt Eure wieder her."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "Ausgeschaltet – die Anzeige, die dieser Kampf eingefroren hat, bleibt bis zum Kampfende sichtbar, und ein Klick wirkt noch ihren Zauber."
L["Switched off -- no prompt will appear."] = "Ausgeschaltet – es erscheint keine Anzeige."
L["Unlocked, but in this fight the prompt stays as the fight found it, and a press still casts it; it can be dragged once the fight ends."] = "Entsperrt, aber in diesem Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und ein Klick wirkt noch ihren Zauber; verschieben lässt sie sich nach dem Kampf."
L["Unlocked -- the prompt this fight froze stays up until it ends, and a press still casts it; then it can be dragged."] = "Entsperrt – die Anzeige, die dieser Kampf eingefroren hat, bleibt bis zum Kampfende sichtbar, und ein Klick wirkt noch ihren Zauber; danach lässt sie sich verschieben."
L["Unlocked, and snoozed until %s -- the prompt stays up to be dragged, casting nothing, until you lock it."] = "Entsperrt und pausiert bis %s – die Anzeige bleibt zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt."
L["Unlocked -- the prompt is up to be dragged and casts nothing until you lock it (%s)."] = "Entsperrt – die Anzeige ist zum Verschieben sichtbar und wirkt nichts, bis Ihr sie sperrt (%s)."
L["Snoozed until %s -- in this fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "Pausiert bis %s – in diesem Kampf bleibt die Anzeige, wie sie bei Kampfbeginn war, und folgt der Pause, sobald der Kampf vorbei ist."
L["Snoozed until %s, %s from now -- no prompt until then."] = "Pausiert bis %s, noch %s – bis dahin keine Anzeige."
L["Nothing to do: your own buffs are switched off under %s."] = "Nichts zu tun: Eure eigenen Stärkungszauber sind unter „%s“ ausgeschaltet."
L["Kept away while you are mounted -- %s, on the %s tab."] = "Ferngehalten, solange Ihr auf einem Reittier seid – „%s“ auf dem Reiter „%s“."
L["Watching your own buffs."] = "Achtet auf Eure eigenen Stärkungszauber."
L["Watching your own buffs; nothing is offered to anybody else: %s."] = "Achtet auf Eure eigenen Stärkungszauber; niemand sonst bekommt etwas angeboten: %s."
L["Nothing to do: %s"] = "Nichts zu tun: %s"
L["Nothing to cast on this character -- /manners debug says why."] = "Dieser Charakter kann nichts wirken – /manners debug sagt, warum."
L["Nothing will be offered: %s."] = "Es wird nichts angeboten: %s."
L["Nothing learned to cast yet."] = "Noch nichts zum Wirken erlernt."
L["Watching for people to buff."] = "Hält Ausschau nach Spielern, die gestärkt werden können."
L["Held in combat -- the prompt moves on once the fight ends."] = "Im Kampf eingefroren – die Anzeige macht nach dem Kampf weiter."
